setup:
cat > ${EVIDENCE}/udhcpc.script <<'EOF'
#!/bin/sh
# udhcpc calls this with deconfig / bound / renew / leasefail / nak; it applies what the server sent
case "$1" in
  deconfig) ip -4 addr flush dev "$interface"; ip link set "$interface" up ;;
  bound|renew) ip -4 addr flush dev "$interface"; ip addr add "$ip/${mask:-24}" dev "$interface"
     [ -n "$router" ] && ip route replace default via ${router%% *} dev "$interface"
     echo "udhcpc $1: $ip/$mask router $router dns $dns lease $lease server $serverid" ;;
  leasefail|nak) echo "udhcpc $1" ;;
esac
EOF
chmod 755 ${EVIDENCE}/udhcpc.script

run:
ip netns exec nl-dhcp-switch nft -f - <<'EOF'
table bridge snoop {
  chain fw { type filter hook forward priority 0; iifname != "p1" iifname != "p6" udp sport 67 counter drop
  }
}
EOF
ip netns exec nl-dhcp-c3 tcpdump -i eth0 -n --immediate-mode -U -w ${EVIDENCE}/snooped.pcap 'udp port 67 or udp port 68' 2>/dev/null & T=$!; sleep 1; ip netns exec nl-dhcp-c3 busybox udhcpc -i eth0 -s ${EVIDENCE}/udhcpc.script -n -q -t 4 -T 4 2>&1 | grep -E 'udhcpc (bound|leasefail|nak)|lease of|no lease'; sleep 0.5; kill -INT $T; wait $T 2>/dev/null; echo '--- on the wire:'; ${EVIDENCE}/dhcp-decode ${EVIDENCE}/snooped.pcap; ip netns exec nl-dhcp-switch nft list chain bridge snoop fw | grep -o 'counter packets [0-9]*'; ip netns exec nl-dhcp-switch nft delete table bridge snoop; kill $(cat ${EVIDENCE}/rogue.pid); rm -f ${EVIDENCE}/rogue.pid
